/**
 * DSH Piggy — the pig as a standalone desktop pet (Windows + macOS).
 *
 * No Claude Code, no terminal: double-click and the pig sits in the corner of
 * the screen. Electron's main process is Node, so the adapter's panel server
 * (`pig/lib/server.js`, generated by `npm run sync`) runs in-process and the
 * window shows the unmodified upstream panel from it.
 */

import { app, BrowserWindow, ipcMain, Menu, nativeImage, powerMonitor, screen, Tray } from 'electron'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { LANGS, LANG_NAMES, tr } from './pig/i18n.js'
import { startServer } from './pig/lib/server.js'
import { readSnapshot } from './pig/lib/status.js'
import { createUpdater } from './updater.mjs'

const HERE = dirname(fileURLToPath(import.meta.url))
// Room for the panel above a 200 px (120 kg) pig, and for the player to
// resize the panel bigger; everything transparent in it is click-through.
const WIDTH = 760
const MAX_HEIGHT = 1200
const windowSize = () => ({ width: WIDTH, height: Math.min(MAX_HEIGHT, screen.getPrimaryDisplay().workArea.height - 16) })
// Fixed so the page's origin (and its remembered UI state) is stable.
const PREFERRED_PORT = 41727

let server = null
let win = null
let tray = null
let quitting = false
let trayLang = null
let panelWin = null
const updater = createUpdater({
  translate: (zh, params) => tr(currentLang(), zh, params),
  onChange: () => refreshTray(true),
})

/** The pig's language, read from the save (the panel may have just changed it). */
function currentLang() {
  try { return readSnapshot(userFile('state.json')).lang } catch { return 'zh' }
}

/** One operation on the pig, through the same route the panel uses. */
async function postAct(body) {
  try {
    await fetch(server.url + 'dsh-pig/act', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
    })
  } catch { /* the next refresh shows whatever stuck */ }
}

async function setLang(lang) {
  await postAct({ action: 'lang', lang })
  refreshTray(true)
}

/**
 * [dsh-piggy-claude-code mod] The pig sleeps when the computer does. The nap
 * is marked `auto`, so waking the computer ends only a nap it started: a pig
 * put to bed by hand sleeps on. Time spent suspended is settled on wake-up,
 * from timestamps, as sleep.
 */
function followSystemSleep() {
  powerMonitor.on('suspend', () => { postAct({ action: 'sleep', auto: true }) })
  powerMonitor.on('resume', () => { postAct({ action: 'wake', auto: true }) })
}

const userFile = name => join(app.getPath('userData'), name)

function readJson(file, fallback) {
  try { return JSON.parse(readFileSync(file, 'utf8')) } catch { return fallback }
}

async function openServer(statePath) {
  try {
    return await startServer({ port: PREFERRED_PORT, statePath })
  } catch (error) {
    if (error?.code !== 'EADDRINUSE') throw error
    return startServer({ port: 0, statePath })
  }
}

// ---- window placement ------------------------------------------------------

function defaultPosition() {
  const area = screen.getPrimaryDisplay().workArea
  const size = windowSize()
  return { x: area.x + area.width - size.width - 8, y: area.y + area.height - size.height - 8 }
}

/** The pig sits in the window's bottom-right corner; keep that corner visible. */
function onScreen({ x, y }) {
  const size = windowSize()
  const corner = { x: x + size.width - 90, y: y + size.height - 90, width: 90, height: 90 }
  return screen.getAllDisplays().some(({ workArea: a }) =>
    corner.x < a.x + a.width && corner.x + corner.width > a.x && corner.y < a.y + a.height && corner.y + corner.height > a.y)
}

/**
 * Where the pig is: the window's bottom-right corner, since the pig lives
 * there and the window's size can change between versions. Older saves kept
 * the top-left of the 340×800 window; convert those.
 */
function savedPosition() {
  const saved = readJson(userFile('window.json'), null)
  const size = windowSize()
  let anchor = null
  if (saved && Number.isFinite(saved.right) && Number.isFinite(saved.bottom)) anchor = saved
  else if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) anchor = { right: saved.x + 340, bottom: saved.y + 800 }
  if (anchor === null) return defaultPosition()
  const position = { x: anchor.right - size.width, y: anchor.bottom - size.height }
  return onScreen(position) ? position : defaultPosition()
}

function savePosition() {
  if (win === null) return
  const { x, y, width, height } = win.getBounds()
  try { writeFileSync(userFile('window.json'), JSON.stringify({ right: x + width, bottom: y + height })) } catch { /* not worth failing over */ }
}

// ---- the pig window ----------------------------------------------------------

function createWindow(url) {
  win = new BrowserWindow({
    ...windowSize(),
    ...savedPosition(),
    frame: false,
    transparent: true,
    backgroundColor: '#00000000',
    hasShadow: false,
    resizable: false,
    maximizable: false,
    minimizable: false,
    fullscreenable: false,
    skipTaskbar: true,
    alwaysOnTop: true,
    show: false,
    webPreferences: { preload: join(HERE, 'preload.cjs'), contextIsolation: true },
  })
  win.setAlwaysOnTop(true, 'floating')
  win.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true })
  // Clicks pass through until the pointer is over the pig; `forward` keeps
  // mouse moves coming so the page can tell us when that happens.
  win.setIgnoreMouseEvents(true, { forward: true })
  win.once('ready-to-show', () => win.showInactive())
  win.on('close', event => {
    if (!quitting) {
      event.preventDefault()
      win.hide()
    }
  })
  // Never hand a URL to the system browser (it may be the retired IE 11).
  win.webContents.setWindowOpenHandler(() => ({ action: 'deny' }))
  win.loadURL(url)
  if (process.env.PIGGY_DEBUG_SNAPSHOT) win.webContents.once('did-finish-load', () => selfCheck(process.env.PIGGY_DEBUG_SNAPSHOT))
}

ipcMain.on('pig', (event, message) => {
  if (win === null || event.sender !== win.webContents || typeof message !== 'object' || message === null) return
  switch (message.type) {
    case 'hit':
      win.setIgnoreMouseEvents(message.hit !== true, { forward: true })
      break
    case 'drag': {
      const [x, y] = win.getPosition()
      win.setPosition(Math.round(x + Number(message.dx || 0)), Math.round(y + Number(message.dy || 0)))
      break
    }
    case 'dragEnd':
      savePosition()
      break
    case 'openPanel':
      openPanelWindow()
      break
    // The panel just opened: take focus so clicking anywhere else blurs the
    // window and the panel closes itself.
    case 'panel':
      if (message.open === true && !win.isFocused()) win.focus()
      break
    default:
      break
  }
})

/**
 * The big panel in a window of our own. It used to open in the system browser,
 * which on some Windows machines is still the retired Internet Explorer 11 and
 * only shows "IE 11 is no longer supported"; our own Chromium always works.
 */
function openPanelWindow() {
  if (panelWin !== null && !panelWin.isDestroyed()) {
    panelWin.show()
    panelWin.focus()
    return
  }
  panelWin = new BrowserWindow({
    width: 1100,
    height: 760,
    minWidth: 420,
    minHeight: 560,
    title: 'DSH Piggy',
    autoHideMenuBar: true,
    backgroundColor: '#f7f3df',
    icon: join(HERE, 'build', 'tray@2x.png'),
    webPreferences: { contextIsolation: true },
  })
  panelWin.webContents.setWindowOpenHandler(() => ({ action: 'deny' }))
  panelWin.on('closed', () => { panelWin = null })
  panelWin.loadURL(server.url + '?standalone=1')
}

// ---- tray / menu-bar icon -------------------------------------------------------

function trayMenu() {
  const visible = win?.isVisible() === true
  const lang = currentLang()
  const t = zh => tr(lang, zh)
  return Menu.buildFromTemplate([
    { label: visible ? t('隐藏猪猪') : t('显示猪猪'), click: () => { visible ? win.hide() : win.showInactive(); refreshTray(true) } },
    { label: t('猪猪回到右下角'), click: () => { win.setPosition(...Object.values(defaultPosition())); savePosition(); win.showInactive() } },
    { label: t('打开大面板'), click: openPanelWindow },
    { type: 'separator' },
    {
      label: '🌐 ' + t('语言'),
      submenu: LANGS.map(key => ({
        label: LANG_NAMES[key],
        type: 'radio',
        checked: key === lang,
        click: () => setLang(key),
      })),
    },
    {
      label: t('开机自动启动'),
      type: 'checkbox',
      checked: app.getLoginItemSettings().openAtLogin,
      click: item => app.setLoginItemSettings({ openAtLogin: item.checked }),
    },
    { type: 'separator' },
    ...updater.menuItems(),
    { label: t('退出'), click: () => app.quit() },
  ])
}

/** Rebuild the menu when the language changed (from the panel or the menu). */
function refreshTray(force = false) {
  if (tray === null) return
  const lang = currentLang()
  if (!force && lang === trayLang) return
  trayLang = lang
  tray.setContextMenu(trayMenu())
}

function createTray() {
  const icon = nativeImage.createFromPath(join(HERE, 'build', 'tray.png'))
  tray = new Tray(icon)
  tray.setToolTip('DSH Piggy')
  refreshTray(true)
  tray.on('click', () => { if (process.platform === 'win32') tray.popUpContextMenu(trayMenu()) })
  setInterval(() => refreshTray(), 3000).unref?.()
}

// ---- self-check (no screen recording needed) ------------------------------------

async function selfCheck(dir) {
  const { mkdirSync } = await import('node:fs')
  mkdirSync(dir, { recursive: true })
  await new Promise(resolve => setTimeout(resolve, 2500))
  const js = code => win.webContents.executeJavaScript(code).catch(error => `error: ${error.message}`)
  const hit = (x, y) => `(()=>{const e=document.elementFromPoint(${x},${y});return !!(e&&e.closest('[data-dsh-pig]'))})()`
  const report = [`bounds=${JSON.stringify(win.getBounds())} visible=${win.isVisible()} onTop=${win.isAlwaysOnTop()}`]
  writeFileSync(join(dir, 'closed.png'), (await win.webContents.capturePage()).toPNG())
  report.push(`hit(empty)=${await js(hit(20, 20))}`)
  report.push(`hit(pig)=${await js(`(()=>{const r=document.querySelector('.dp-scene').getBoundingClientRect();return ${hit('r.left+r.width/2', 'r.top+r.height/2')}})()`)}`)
  report.push(`bridge=${await js('typeof window.webkit?.messageHandlers?.pig?.postMessage')}`)
  await js(`document.querySelector('.dp-scene').dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true}))`)
  await new Promise(resolve => setTimeout(resolve, 1000))
  writeFileSync(join(dir, 'open.png'), (await win.webContents.capturePage()).toPNG())
  report.push(`open=${await js(`document.querySelector('[data-dsh-pig]').getAttribute('data-open')`)}`)
  report.push(`art=${await js(`(()=>{const i=document.querySelector('[data-dsh-pig] img');return i?i.src+' '+i.naturalWidth+'x'+i.naturalHeight+' hidden='+i.hidden:'none'})()`)}`)
  report.push(`statePath=${userFile('state.json')}`)
  // The big panel opens in our own window, never the system browser.
  openPanelWindow()
  await new Promise(resolve => panelWin.webContents.once('did-finish-load', resolve))
  await new Promise(resolve => setTimeout(resolve, 2000))
  writeFileSync(join(dir, 'panel.png'), (await panelWin.webContents.capturePage()).toPNG())
  const panelJs = code => panelWin.webContents.executeJavaScript(code).catch(error => `error: ${error.message}`)
  report.push(`panel url=${panelWin.webContents.getURL()} mounted=${await panelJs("!!document.querySelector('[data-dsh-pig]')")} claudeCodeHint=${await panelJs("!!document.querySelector('[data-hint=\"why\"]')")}`)
  writeFileSync(join(dir, 'report.txt'), report.join('\n') + '\n')
}

// ---- lifecycle --------------------------------------------------------------------

// Tests and self-checks keep their save (and window position) out of the real profile.
if (process.env.PIGGY_USER_DATA) app.setPath('userData', process.env.PIGGY_USER_DATA)

if (!app.requestSingleInstanceLock()) {
  app.quit()
} else {
  app.on('second-instance', () => win?.showInactive())
  // A plain SIGTERM would skip before-quit and lose the last unsaved moments.
  for (const signal of ['SIGTERM', 'SIGINT']) process.on(signal, () => app.quit())
  app.on('window-all-closed', () => { /* stay in the tray */ })
  app.on('before-quit', () => {
    quitting = true
    savePosition()
    // close() flushes the save synchronously before it resolves.
    server?.close()
  })

  app.whenReady().then(async () => {
    app.dock?.hide()
    // A brand-new pig speaks the system language; existing saves keep theirs.
    if (!process.env.PIG_LANG) process.env.PIG_LANG = app.getLocale()
    server = await openServer(userFile('state.json'))
    createWindow(server.url + 'desk')
    createTray()
    followSystemSleep()
    updater.start()
  })
}
